/* Tradex help · ERP · Orders (erp-orders.html) */
TX.help.add({
  /* ------------------------------------------------------------------ page-local glossary terms (to merge into glossary.js) */

  /* ------------------------------------------------------------------ page guide */
  "page": { t: "Orders", k: "Page guide",
    what: "The list of every order from every channel — website, WhatsApp, branch counter (POS) and orders staff place for customers — and the place to follow each one from the moment it is placed until it is delivered.",
    why: "An order involves the customer, support, finance, the warehouse and the courier. For every order this page shows three separate statuses — the order itself, the payment and the fulfilment (warehouse and courier) — so everyone can see what is done, what is waiting and who must act. It never squeezes them into one status.",
    read: ["<b>How orders work</b> (top) shows the six steps every order goes through. Click a step to list the orders at it.",
      "<b>Summary tiles</b> give today's totals, such as orders waiting for payment or needing action.",
      "<b>Filters</b> narrow the list by date, location, channel, buyer type and payment state.",
      "<b>Saved views</b> above the table (All orders, Needs action, Awaiting payment…) are ready-made work queues. The blue line under them explains the view you are on.",
      "Click an order to open the <b>order view</b> on the right. Its <b>Next step</b> box says what to do now."],
    do: ["Start with <b>Needs action</b> — orders that are stopped until someone decides — and anything with a red SLA flag.",
      "Open each order and follow its Next step box. Record every decision with a reason.",
      "Use <b>New assisted order</b> for customers ordering by phone, on WhatsApp or at the counter."],
    next: "Paid orders are picked, packed and handed to the courier on <b>Pick · pack · dispatch</b>. Refund requests from cancelled lines are approved and paid by finance. Returns after delivery become cases on <b>Returns &amp; warranty</b>.",
    notes: ["Order, payment and fulfilment statuses are separate on purpose: a payment can be captured while the order is on hold, and a courier update never changes the order or payment status.",
      "In this prototype the saved-view counts are worked out from the sample orders listed, so they can differ from the summary tiles, which count all 148 orders.",
      "Times, limits, reservation lengths and provider names (Razorpay, Delhivery) are sample values; the real rules are set by the business."],
    map: [["flow", "The six steps of an order"], ["kpi-needs", "Today's totals"], ["filters", "Narrow the list"], ["sync-alert", "Courier sync warning"], ["sv-all", "Saved views (work queues)"], ["orders-table", "The orders list"], ["states-3", "Why there are three statuses"], ["d-order", "Working one order"], ["m-cancel", "Cancelling lines"], ["m-hold", "Putting an order on hold"], ["m-assisted", "Creating an order for a customer"]],
    terms: ["channel", "state-machine", "reservation", "allocation", "sla", "b2b", "b2c"] },

  "act-picklists": { t: "Print pick lists", k: "Button",
    what: "Prints the pick lists for orders already released to the warehouse, on the warehouse printer.",
    why: "A pick list tells the picker which items to collect and from which bin. Only paid orders with stock allocated are released, so only those are printed.",
    notes: ["To print lists for a few chosen orders only, tick them in the list and use <b>Print pick lists</b> in the bulk bar."],
    terms: ["pick-pack", "bin"], rel: ["bulk"] },
  "act-assisted": { t: "New assisted order", k: "Button",
    what: "Opens the form for creating an order on behalf of a customer who is on the phone, on WhatsApp or at a branch counter.",
    next: "The customer then confirms and pays through a secure checkout link (or at the counter), exactly like a website order.",
    terms: ["assisted", "checkout-link"], rel: ["m-assisted"] },

  "flow": { t: "How orders work", k: "Guide",
    what: "The six steps every order passes through, in order, with how many orders are at each step and who does the work.",
    read: ["Each box is one step: what happens, who is involved and how many orders are there.",
      "The <b>amber</b> box is the step that needs people's attention most. A green number shows finished orders.",
      "Click a box to show those orders in the list below. Steps 1 and 2 open a saved view; steps 3 to 6 filter the list (the blue line under the saved views says which step you are looking at, with <b>Show all orders</b> to go back)."],
    lists: [{ h: "The steps", items: [
      ["1 · Take the order", "The customer orders on the website, on WhatsApp or at a branch, or staff place it for them. The system works out the price and reserves the stock for a short time."],
      ["2 · Receive payment", "The customer pays. The order is confirmed only when the payment provider confirms the money — then the stock is allocated and the invoice is created. Unpaid reservations expire and free the stock."],
      ["3 · Clear approvals & holds", "Some orders stop for a person: a staff discount above their authority (before any payment link), a GSTIN check, a payment that arrived after the reservation expired, or a stock problem."],
      ["4 · Pick & pack", "Paid orders with allocated stock go to the warehouse queue. Staff scan every item and serial number, then pack and label the parcel."],
      ["5 · Dispatch & track", "The courier collects the parcel. Tracking updates change only the fulfilment status. Failed deliveries are followed up with the customer."],
      ["6 · Deliver & close", "The customer has the goods. A later return is handled as a separate case on Returns & warranty."]] }],
    notes: ["Cancellations can happen at any step before dispatch — see [[sv-cancel]].", "Use <b>Hide guide</b> once you know the steps — the page remembers your choice. <b>Show how it works</b> brings it back.", "The counts are from the sample orders in this prototype."],
    terms: ["reservation", "capture", "allocation", "pick-pack", "canonical-status"] },

  /* ------------------------------------------------------------------ summary tiles */
  "kpi-today": { t: "Orders today", k: "Summary tile",
    what: "How many orders were placed today, across all channels.",
    read: "“+9% vs last Sat” compares with the same weekday last week. The small line shows the trend over recent days." },
  "kpi-awaiting": { t: "Awaiting payment", k: "Summary tile",
    what: "Orders that were placed but are not paid yet.",
    read: "“₹3.42 L in live reservations” is the value of stock currently held for these orders. If an order is not paid in time, its reservation expires and the stock can be sold again.",
    rel: ["sv-awaiting"], terms: ["reservation"] },
  "kpi-needs": { t: "Needs action", k: "Summary tile",
    what: "Orders that are stopped until a person acts: approvals, holds, cancellation requests, failed deliveries and overdue dispatches.",
    read: "“Oldest 26 h” is how long the oldest one has waited. A <b>critical</b> one (for example a payment that arrived after its reservation expired) should be handled first.",
    rel: ["sv-needs"] },
  "kpi-overdue": { t: "Overdue dispatch", k: "Summary tile",
    what: "Paid orders that have missed their promised dispatch time.",
    read: "“−3 vs last week” in green means three fewer than a week ago — an improvement. Open them from the Needs action view; the order's alert box says what is blocking it.",
    rel: ["col-sla", "x-overdue"] },
  "kpi-p2d": { t: "Paid → dispatched", k: "Summary tile",
    what: "The average time between the payment being confirmed and the parcel being handed to the courier.",
    read: "Lower is better. The green arrow shows it is 1.4 hours faster than the previous period; the small line shows the trend." },
  "kpi-cancel": { t: "Cancel requests", k: "Summary tile",
    what: "Open requests from customers or dealers to cancel all or part of an order, and the value involved.",
    read: "“SLA 4 h” is the target time to reply to a request — a sample value set by the business.",
    rel: ["sv-cancel"], terms: ["sla"] },

  /* ------------------------------------------------------------------ filters & alerts above the list */
  "filters": { t: "Filters", k: "Filter",
    what: "Narrow the orders list. Filters combine with the saved view or step you are on.",
    lists: [{ h: "Filters", items: [
      ["Search", "Order number, customer name, product name or serial number."],
      ["Date range", "When the order was placed (today, last 7 or 30 days, this financial year, or a custom range)."],
      ["Location", "The warehouse or branch the order is fulfilled from."],
      ["Channel", "Web, Branch POS, WhatsApp or Assisted (placed by staff)."],
      ["Buyer type", "Consumers (B2C) or approved dealers (B2B)."],
      ["Payment state", "Not started, Pending, Failed, Captured, COD · due on delivery or Refunded — see [[col-pay]]."],
      ["Reset", "Clears every filter (and any step chosen in How orders work)."]] }],
    terms: ["channel", "b2c", "b2b", "fy"], rel: ["col-pay", "col-channel"] },
  "sync-alert": { t: "Courier status sync paused", k: "Alert",
    what: "The background job that fetches parcel tracking from the courier stopped at 08:15 after the courier's system timed out (it retried automatically three times).",
    read: "Only the fulfilment status of parcels already dispatched may be out of date (17 shipments here). Order and payment statuses come from other sources and are correct.",
    do: ["Click <b>Sync now</b> to try again by hand.", "<b>View job</b> opens the job on the Automation page for details.", "Until it recovers, treat the tracking shown for dispatched parcels as possibly behind."],
    terms: ["sync", "job-queue", "awb"] },

  /* ------------------------------------------------------------------ saved views (tabs) */
  "sv-all": { t: "All orders", k: "Tab",
    what: "Every order from every channel, one row each, newest first. The saved views next to it are ready-made work queues taken from this list.",
    why: "It is the complete picture: one place where support, finance and the warehouse see the same orders and the same statuses.",
    read: ["Each row shows the order, the buyer, the channel and location, the value, then <b>three separate statuses</b> — order, payment and fulfilment — and the next deadline.",
      "An amber or red line under the order number says why it needs attention."],
    do: ["Use the saved views, the filters or the How orders work steps to focus on one kind of work.", "Click a row to open the order and follow its Next step box.", "Tick several rows to act on them together (bulk bar)."],
    next: "Orders move from view to view by themselves as their statuses change — for example from Awaiting payment to the warehouse queue once paid.",
    terms: ["channel", "state-machine"], rel: ["orders-table", "states-3", "bulk", "sv-save"] },
  "sv-needs": { t: "Needs action", k: "Tab",
    what: "Orders that are stopped until a person acts.",
    why: "Routine orders flow on their own; this queue collects only the exceptions, so nothing waits unnoticed.",
    lists: [{ h: "Why an order is here", items: [
      ["Approval needed", "A staff discount above the person's authority (or below the margin floor). The order stays a <b>Draft</b> until approved."],
      ["On hold", "Stopped on purpose — for example a GSTIN mismatch, or a payment that arrived after the reservation expired.", "s-bad"],
      ["Cancel req.", "The customer or dealer asked to cancel a line or the whole order.", "b-warn"],
      ["Delivery failed", "The courier could not deliver; the customer must be contacted before the next attempt.", "s-bad"],
      ["Overdue dispatch", "Paid but not dispatched in time — for example the stock was not in its bin."]] }],
    do: ["Work red (critical or overdue) first, then amber.", "Open each order: the red or amber box says what happened, and the Next step box says who must do what.", "Record each decision with a reason — it goes into the order's audit trail."],
    next: "When the issue is resolved the order leaves this view and continues its normal steps.",
    notes: ["Even when orders are handled together, each order keeps its own decision history."],
    terms: ["exception", "sla", "approval"], rel: ["x-late", "x-gstin", "x-approval", "x-cancel-req", "x-failed", "x-overdue"] },
  "sv-awaiting": { t: "Awaiting payment", k: "Tab",
    what: "Orders that were placed but are not paid yet. Their stock is reserved for a short time while the customer pays.",
    why: "Reserving the stock stops two customers buying the same last unit, while the time limit makes sure unpaid orders do not block stock for long.",
    lists: [{ h: "Payment states you will see", items: [
      ["Not started", "The checkout link was sent; the customer has not tried to pay yet.", "s-muted"],
      ["Pending", "A payment is in progress — for example a UPI request waiting for approval in the customer's app.", "s-warn"],
      ["Failed", "The last attempt failed. The customer can retry with the same link while the reservation lasts.", "s-bad"]] }],
    do: ["Nothing needs confirming by hand: the order confirms itself when the payment provider confirms the money.", "If a reservation is about to expire (see the SLA column), tick the order and use <b>Send payment reminder</b>."],
    next: "Once the payment is captured: the order becomes <b>Confirmed</b>, the reservation becomes an allocation, the invoice is created and a pick task goes to the warehouse. If nobody pays in time, the reservation expires and the stock is released. A payment that arrives after that is held for finance (see [[x-late]]).",
    notes: ["The 30-minute reservation shown in the prototype is a sample value."],
    terms: ["reservation", "capture", "checkout-link", "upi"], rel: ["col-pay", "d-reservation"] },
  "sv-hold": { t: "On hold", k: "Tab",
    what: "Orders stopped on purpose before the warehouse can start.",
    why: "When something must be checked — a tax number, a suspicious payment, a stock problem — a hold stops the order from being picked and shipped, while keeping the payment and the stock reservation.",
    lists: [{ h: "Common reasons", items: [
      ["Customer request — confirm details", "The customer asked to change or confirm something first."],
      ["Address / GSTIN verification", "The address or the dealer's GST number must be checked before invoicing or shipping."],
      ["Payment review", "The payment does not match or looks risky — also used automatically when a payment arrives after its reservation expired."],
      ["Stock exception", "The stock is not where the system says it is."],
      ["Awaiting approval", "A decision from someone with authority is needed."]] }],
    do: ["Open the order: its red box says why it is held and who owns the hold.", "Fix the issue by the review time.", "Use <b>Release hold</b> (in the order's red box) when it is resolved."],
    next: "After release, the order goes back to the warehouse pick queue.",
    notes: ["If a hold passes its review time, it escalates once to the operations manager. The reservation is extended while on hold (up to 48 h in the prototype — a sample limit)."],
    terms: ["gstin", "reservation"], rel: ["m-hold", "x-gstin", "x-late"] },
  "sv-partial": { t: "Partially fulfilled", k: "Tab",
    what: "Orders where some lines have shipped and the rest will ship later — for example an item arriving by stock transfer from another location, or from a supplier's stock.",
    read: "The order state is <b>Partially fulfilled</b> and the fulfilment status is <b>Partly dispatched</b>. The SLA column shows when the remaining line is due.",
    do: ["Open the order's <b>Shipments</b> tab to see what has shipped and what is still coming.", "If the remaining line will be late, tell the customer."],
    next: "When the last line ships, the order becomes <b>Fulfilled</b>.",
    notes: ["In these samples the split shipment was agreed with the customer at checkout. Whether and when partial dispatch is offered is to be confirmed by the client."],
    terms: ["transfer", "partner-stock"], rel: ["d-shipments"] },
  "sv-cancel": { t: "Cancellation requests", k: "Tab",
    what: "Requests from customers or dealers to cancel one line or a whole order.",
    why: "A cancellation touches stock and money, so it is decided by a person, before the parcel leaves.",
    read: "The SLA column shows the time by which the request should be answered.",
    do: ["Open the order and click <b>Review cancellation</b> (or <b>Cancel lines…</b> at the bottom).", "Tick the lines to cancel, choose the reason and check the refund preview.", "Confirm. Lines that have already shipped cannot be cancelled — they come back through a return after delivery."],
    next: "The cancelled lines' stock is released (picked items go back to their bin), a refund request goes to finance, and the customer is notified. Finance approves and pays the refund.",
    notes: ["Support never pays refunds directly — support requests, finance executes."],
    terms: ["refund", "cn", "idempotency"], rel: ["m-cancel", "x-cancel-req"] },
  "sv-save": { t: "Save view", k: "Button",
    what: "Saves the current saved view and filters under a name, for you or your team — for example “Dealer orders · WH-BLR”.",
    notes: ["The button with the sliders icon next to it chooses which columns are shown."] },

  /* ------------------------------------------------------------------ list */
  "bulk": { t: "Bulk actions", k: "Toolbar",
    what: "Appears when you tick one or more orders, so you can act on several at once.",
    lists: [{ h: "Buttons", items: [
      ["Release to fulfilment", "Sends the ticked orders to the warehouse queue. Only eligible orders (paid, with stock reserved) are released; the others are skipped."],
      ["Print pick lists", "Prints the pick lists for the ticked orders."],
      ["Assign…", "Gives the ticked orders to a team member."],
      ["Place on hold", "Opens the hold form for the ticked orders."],
      ["Send payment reminder", "Sends a reminder to customers with unpaid orders. Customers who opted out of messages are skipped."],
      ["Export", "Downloads the ticked orders as a spreadsheet (CSV)."]] }],
    notes: ["Each order keeps its own decision history, even when handled in bulk."],
    terms: ["consent", "csv"], rel: ["m-hold"] },
  "orders-table": { t: "Orders list", k: "Table",
    what: "One row per order. Click a row to open the order view.",
    lists: [{ h: "Columns", items: [
      ["Order", "Order number, and when it was placed or why it needs attention."],
      ["Buyer", "Customer or dealer, with a badge for consumer or dealer price tier."],
      ["Channel", "Where the order came from."],
      ["Loc.", "The location that fulfils the order."],
      ["Value", "The order total including GST, and the number of units."],
      ["Order state · Payment · Fulfilment", "The three separate statuses — see [[states-3]]."],
      ["SLA flag · age", "The next deadline, and how long ago the order was placed."]] }],
    rel: ["col-order", "col-buyer", "col-channel", "col-loc", "col-ord", "col-pay", "col-ful", "col-sla"] },
  "states-3": { t: "Three separate statuses", k: "Rule",
    what: "Every order has three separate statuses, each with its own list of values and rules: the <b>order</b> (is it agreed and still open?), the <b>payment</b> (has the money been received?) and the <b>fulfilment</b> (where are the goods?). Returns have a fourth one of their own.",
    why: "Real orders do not move in one straight line: a payment can be captured while the order is on hold for a check; one line can ship while another is cancelled; a courier's update must never change what finance knows about the payment.",
    read: "Read the three together. For example <b>On hold · Captured · Allocated</b> means the money is received and the stock is set aside, but the warehouse must not start yet.",
    terms: ["state-machine"], rel: ["col-ord", "col-pay", "col-ful", "st-return"] },
  "col-order": { t: "Order", k: "Column",
    what: "The order number (TXO-…). Under it: the date and time it was placed — or, if it needs attention, a short amber or red note saying why (for example “Hold: GSTIN mismatch on invoice”). Hover over the note to read it in full." },
  "col-buyer": { t: "Buyer", k: "Column",
    what: "Who placed the order. The grey <b>Consumer</b> badge means public prices (including GST). A teal badge with a briefcase shows an approved dealer and their price tier — for example Dealer Gold or Dealer Standard — with prices before GST and a business (B2B) tax invoice.",
    terms: ["b2c", "b2b", "price-list"] },
  "col-channel": { t: "Channel", k: "Column",
    what: "Where the order came from. All channels use the same prices, stock and payment rules.",
    lists: [{ h: "Values", items: [
      ["Web", "Placed by the customer on the website."],
      ["POS", "Billed at a branch counter (point of sale)."],
      ["WhatsApp", "Agreed in a WhatsApp chat as a draft basket, then confirmed and paid through a secure checkout link."],
      ["Assisted", "Placed by staff for a customer — on the phone, on WhatsApp or at the counter."]] }],
    terms: ["channel", "pos", "draft-basket", "assisted"] },
  "col-loc": { t: "Loc. (location)", k: "Column",
    what: "The warehouse or branch that fulfils the order. Hover over the code to see the full name.",
    lists: [{ h: "Values", items: [
      ["WH-BLR", "Central Warehouse, Bengaluru"], ["BR-SPR", "SP Road Branch, Bengaluru"],
      ["BR-KRM", "Koramangala Branch, Bengaluru"], ["BR-MYS", "Mysuru Branch"]] }] },
  "col-ord": { t: "Order state", k: "Statuses",
    what: "The status of the order itself — whether it is agreed, paid for, being fulfilled or finished. In the order view it is the first of the status boxes.",
    lists: [{ h: "Statuses", items: [
      ["Draft", "Created by staff but not sent to the customer yet — for example waiting for a discount approval. No stock is reserved.", "s-muted"],
      ["Awaiting payment", "Placed, with stock reserved for a short time; waiting for the payment to be confirmed.", "s-warn"],
      ["Confirmed", "Paid (or accepted as cash on delivery) and stock allocated — the warehouse can work on it.", "s-brand"],
      ["On hold", "Stopped on purpose until a person resolves an issue. Payment and stock are kept.", "s-bad"],
      ["Partially fulfilled", "Some lines have shipped; others will follow.", "s-info"],
      ["Fulfilled", "Every line has been dispatched. Delivery is still followed under Fulfilment.", "s-ok"],
      ["Cancelled", "Cancelled before dispatch; the stock was released and any payment refunded.", "s-muted"],
      ["Closed", "Complete — nothing more is expected on the order. A later return is handled as a separate case.", "s-ok"]] }],
    read: "In the order view, the small line under the status gives the reason — for example “Guard: paid + stock allocated”, the condition that had to be met for the order to become Confirmed.",
    notes: ["Exactly when a fulfilled order becomes Closed (for example after delivery or after the return window) is to be confirmed by the business."],
    terms: ["state-machine", "reservation", "allocation"], rel: ["states-3"] },
  "col-pay": { t: "Payment", k: "Statuses",
    what: "The status of the customer's payment for the order, as confirmed by the payment provider. In the order view it is the second status box, with the amount and provider underneath.",
    lists: [{ h: "Statuses", items: [
      ["Not started", "No payment attempt yet — the checkout link is sent or about to be sent.", "s-muted"],
      ["Pending", "An attempt is in progress, for example a UPI request waiting in the customer's app.", "s-warn"],
      ["Failed", "The last attempt failed (for example declined by the bank). The customer can try again while the reservation lasts.", "s-bad"],
      ["Captured", "The provider confirmed the money was taken. Only the provider's signed message or a direct check sets this — never the customer's browser.", "s-ok"],
      ["COD · due", "Cash on delivery: the courier collects the money and pays it to Tradex later. It stays due until then.", "s-warn"],
      ["Refunded", "The payment was returned to the customer in full.", "s-muted"]] }],
    notes: ["A late “failed” message never overrides a payment that is already proven captured.", "COD is offered only where the rules allow it (for example the delivery PIN code); in the prototype it is not offered for dealer orders."],
    terms: ["capture", "webhook", "upi", "cod", "refund"], rel: ["d-attempts", "d-webhooks"] },
  "col-ful": { t: "Fulfilment", k: "Statuses",
    what: "Where the goods are — in the warehouse or with the courier. In the order view it is the third status box, with the picker, wave or courier underneath.",
    lists: [{ h: "Statuses", items: [
      ["Unallocated", "No stock assigned to the order yet — normal before payment.", "s-muted"],
      ["Allocated", "Stock (and, for serialised items, the exact unit) set aside for the order; waiting in the pick queue.", "s-brand"],
      ["Picking", "A picker is collecting the items and scanning each serial number. Orders are picked in batches called waves (for example W-26-07).", "s-info"],
      ["Packed", "Checked, packed and labelled; waiting for the courier pickup.", "s-info"],
      ["Partly dispatched", "Some lines have been handed to the courier; the rest follow separately.", "s-info"],
      ["Dispatched", "Handed to the courier. Physical stock is reduced at this moment.", "s-brand"],
      ["Delivered", "The customer has the goods (or collected them at the counter).", "s-ok"],
      ["Delivery failed", "The courier could not deliver (for example the customer was unreachable). Another attempt is made; after the last one the parcel returns to Tradex (RTO).", "s-bad"],
      ["Released", "The order was cancelled and its stock was given back — nothing will ship.", "s-muted"]] }],
    notes: ["Courier updates are translated into these statuses and the courier's original message is kept. They change only the fulfilment status — never the order or the payment."],
    terms: ["allocation", "pick-pack", "serial", "awb", "rto", "canonical-status"], rel: ["d-shipments"] },
  "col-sla": { t: "SLA flag · age", k: "Column",
    what: "The next deadline for the order, and how long ago it was placed.",
    read: "Green = on time · amber = a deadline is close or something is waiting (a reservation or approval about to expire, a reply due) · red = overdue or critical · “—” = nothing due.",
    lists: [{ h: "Examples", items: [
      ["Dispatch by 16:00", "Must be handed to the courier by then."],
      ["Link exp. / Hold exp. 11:01", "The payment link and its stock reservation expire at that time."],
      ["Approval due 12:00", "The approver must decide by then."],
      ["Reply by 13:10", "Deadline to answer a cancellation request."],
      ["At risk · 3 h left", "Close to missing its deadline."],
      ["Overdue · 26 h / Critical", "Already late, or needs immediate action."],
      ["ETA Tue 29 Sep", "Expected delivery date from the courier."]] }],
    notes: ["The target times are set by the business; the ones shown are sample values."],
    terms: ["sla", "eta"] },

  /* ------------------------------------------------------------------ order view (drawer) */
  "d-order": { t: "Order view", k: "Drawer",
    what: "Everything about one order: its lines and prices, payments, shipments, full history and internal notes.",
    read: ["The top shows the order number, the buyer (consumer, or dealer and tier) and where the order came from (for example a WhatsApp draft basket).",
      "Four boxes show the four separate statuses: <b>order</b>, <b>payment</b>, <b>fulfilment</b> and <b>return</b>, each with a short reason underneath.",
      "A red or amber box appears when something is wrong, with the button to fix it.",
      "The blue <b>Next step</b> box always says what to do now for this order, with a button that takes you to the right place."],
    do: ["Read the Next step box and use its button.", "Check the tabs for details: lines and prices, payments, shipments, timeline.", "Record decisions with a reason; add an internal note if colleagues need context."],
    lists: [{ h: "Buttons", items: [
      ["Copy link", "Copies a link that opens this order directly."],
      ["Place on hold", "Stops the order from going to the warehouse — see [[m-hold]]."],
      ["Cancel lines…", "Cancels lines not yet dispatched and requests the refund — see [[m-cancel]]."],
      ["Resend notification", "Sends the order confirmation or tracking message again."],
      ["Add note", "Jumps to the internal notes."],
      ["View invoice", "Opens the tax invoice (it is created only once)."],
      ["Open in fulfilment", "Opens the order on the warehouse's Pick · pack · dispatch page."]] }],
    terms: ["state-machine"], rel: ["col-ord", "col-pay", "col-ful", "st-return", "d-tab-lines", "d-tab-pay", "d-tab-ship", "d-tab-time", "d-tab-notes"] },
  "st-return": { t: "Return", k: "Statuses",
    what: "The fourth, separate status: whether any item from this order is being returned. <b>None</b> means there is no return case.",
    read: "The line underneath says whether the order is still within its return window (for example “Eligible until 6 Oct (policy v2026.2)”) or not delivered yet.",
    notes: ["The return window comes from the policy version stored on the order at the time of sale. Returns are handled on Returns & warranty.", "The dates and policy version shown are sample values."],
    terms: ["rma", "policy-version", "snapshot"] },
  "d-tab-lines": { t: "Lines & pricing", k: "Tab",
    what: "What was ordered and at what price: the lines with their allocated units, the price snapshot, the totals, the stock reservation, and the customer and delivery details.",
    rel: ["d-lines", "d-snapshot", "d-totals", "d-reservation", "d-delivery"] },
  "d-tab-pay": { t: "Payments", k: "Tab",
    what: "Everything about the money for this order: each payment attempt, the messages from the payment provider, any refunds and the invoice. The number on the tab is the count of payment attempts.",
    rel: ["d-attempts", "d-webhooks", "d-refunds", "d-invoice"], terms: ["capture"] },
  "d-tab-ship": { t: "Shipments", k: "Tab",
    what: "The parcel or parcels for this order: courier, tracking number and tracking history — or, before shipping, whether the courier can deliver to the address and the promised dispatch time.",
    rel: ["d-shipments"], terms: ["awb", "serviceability"] },
  "d-tab-time": { t: "Timeline & audit", k: "Tab",
    what: "The order's history in time order, and the audit trail of who (a person or an automatic rule) changed what.",
    rel: ["d-timeline", "d-audit"], terms: ["audit"] },
  "d-tab-notes": { t: "Internal notes", k: "Tab",
    what: "Notes staff leave for each other about this order — for example why a line is being held at the pack bench.",
    do: ["Type the note; use @name to notify a colleague.", "Click <b>Add note</b>. The note is also recorded in the order's audit trail."],
    notes: ["Internal notes are visible to staff only and are never sent to the customer."], terms: ["audit"] },

  "d-lines": { t: "Lines", k: "Table",
    what: "Each product on the order, with its condition, quantity, the stock allocated to it and its price.",
    lists: [{ h: "Columns", items: [
      ["Item · condition", "Product, condition badge (new, open box, refurbished, used) and SKU."],
      ["Qty", "Quantity ordered."],
      ["Allocated unit", "For serialised items, the Tradex unit ID (U-…), the maker's serial number and a link to its inspection report (IR-…). Otherwise the quantity allocated; serials are scanned at pick or pack."],
      ["Unit price · rule", "Price per unit — before GST for dealers, including GST for consumers — and the price list, version and quantity tier used."],
      ["Line total", "Quantity × unit price."],
      ["Line status", "The line's fulfilment status, or <b>Cancel req.</b> when the customer asked to cancel that line."]] }],
    terms: ["serial", "condition", "sku", "allocation", "price-list"] },
  "d-snapshot": { t: "Price snapshot", k: "Section",
    what: "The prices and rules frozen on this order when it was placed: the price list and version, the quote and how long it was locked, the check at checkout, any promotion, the discount-combining (stacking) policy and the margin check.",
    why: "Later price changes never change an existing order. For example, a new dealer price list effective 1 Oct does not change this order — it keeps its snapshot.",
    notes: ["The server always works out the price; a price from the customer's browser or a chat is never trusted.", "The stacking policy and margin floor shown are sample values. The exact order in which price lists, quantity tiers and promotions apply is still being confirmed."],
    terms: ["snapshot", "quote", "promotion", "margin", "price-list"] },
  "d-totals": { t: "Totals", k: "Section",
    what: "How the order total is built: subtotal, order discount, GST, shipping and the total.",
    read: ["Dealer orders are priced before GST, and GST is added on top (shown as CGST + SGST for a sale within the same state).", "Consumer prices already include GST; the GST part is shown in brackets.", "The line under the totals says which invoice type applies and the place of supply (the state where the sale is taxed, which decides the GST split)."],
    notes: ["The GST rate depends on each product's HSN code and the tax rules finance approves; the 18% in these samples is illustrative."],
    terms: ["gst", "gst-parts", "hsn", "gstin"] },
  "d-reservation": { t: "Stock reservation", k: "Section",
    what: "The hold on stock created at checkout, so nobody else can buy the same unit while this customer pays.",
    lists: [{ h: "Statuses", items: [
      ["Active", "Stock is held until the time shown; it is released automatically if the order is not paid.", "s-warn"],
      ["Converted to allocation", "The payment was captured, so the reservation became a firm allocation to this order.", "s-ok"],
      ["Expired", "Time ran out before payment and the unit may now be reserved by another order. A payment that arrives later puts the order on hold for finance — stock never goes below zero.", "s-bad"],
      ["No reservation", "Draft orders hold no stock until approved and sent; cancelled orders released theirs."]] }],
    notes: ["The 30-minute hold is a sample value. One shared stock system serves the website, branches and WhatsApp, so the same unit cannot be sold twice."],
    terms: ["reservation", "allocation", "atp"], rel: ["x-late"] },
  "d-delivery": { t: "Customer & delivery", k: "Section",
    what: "The buyer (with GSTIN for dealers), the contact number (partly hidden, marked verified), the delivery address and the delivery promise given at checkout.",
    terms: ["gstin", "serviceability"] },
  "d-attempts": { t: "Payment attempts", k: "Table",
    what: "Each try the customer made to pay: attempt number (PA-1, PA-2…), the provider's reference, method, amount, result, time and detail.",
    read: ["A failed attempt followed by a captured one is normal — for example the bank declined the first try and the customer paid another way.", "“Settlement T+2” means the provider is expected to pay the money into Tradex's bank two days after the payment (settlement terms depend on the provider).", "For cash on delivery the attempt shows <b>Due on delivery</b> until the courier's COD remittance arrives."],
    lists: [{ h: "Statuses", items: [
      ["Pending", "Waiting for the customer or the bank.", "s-warn"], ["Failed", "Did not go through.", "s-bad"],
      ["Captured", "Money taken — the order is paid.", "s-ok"], ["Due on delivery", "Cash on delivery, not collected yet.", "s-warn"]] }],
    terms: ["capture", "settlement", "upi", "cod"] },
  "d-webhooks": { t: "Webhook event log", k: "Table",
    what: "The messages the payment provider sent about this order's payments, in the order they arrived. Each one is checked (signature verified), recorded once, and applied only if it is an allowed next step.",
    why: "Providers can send the same message twice or in the wrong order. Checking and recording each message once means one payment, one invoice and one pick task — never two.",
    lists: [{ h: "Event types", items: [
        ["payment.created", "A payment attempt started."], ["payment.authorized", "The bank approved the payment; the money is not taken yet."],
        ["payment.captured", "The money was taken — the order becomes Confirmed."], ["payment.failed", "The attempt failed."],
        ["order.paid", "The provider's confirmation that the whole order is paid."], ["refund.processed", "A refund was completed."]] },
      { h: "Results", items: [
        ["Applied", "Changed a status (the Effect column says which).", "b-ok"],
        ["Applied (no-op)", "Valid, but there was nothing left to change.", "b-ok"],
        ["Ignored", "A duplicate (same event id already processed) or out of order (for example a late “failed” after a proven capture). Nothing changes.", "badge"]] }],
    do: ["If a message seems to be missing or late, click <b>Reconcile now</b>: Tradex asks the provider directly and compares the result with the order."],
    terms: ["webhook", "idempotency", "reconciliation", "capture"] },
  "d-refunds": { t: "Refunds", k: "Section",
    what: "Refunds made for this order, with their reference, amount, method and status.",
    read: "Line cancellations and returns each create one refund request for finance; only one provider refund is made per request.",
    terms: ["refund", "idempotency", "cn"], rel: ["m-cancel"] },
  "d-invoice": { t: "Invoice", k: "Section",
    what: "The invoice for this order. It is created once, when the payment is confirmed: a business (B2B) tax invoice for dealers, or a consumer (B2C) invoice.",
    notes: ["Repeated payment messages never create a second invoice.", "Whether e-invoicing applies to Tradex is to be confirmed by finance."],
    terms: ["gstin", "irn", "b2b", "b2c"] },
  "d-shipments": { t: "Shipments", k: "Section",
    what: "The parcel for this order: shipment number (SHP-…), courier, tracking number (AWB), number of parcels and weight; how it was booked; the label, handover manifest and handover evidence.",
    read: ["<b>Raw carrier status</b> is the courier's own code and message — for example PU (picked up), IT (in transit), OFD (out for delivery), UD (undelivered; CNEE = consignee, the person receiving).", "<b>Canonical</b> is the standard Tradex status that code was translated into.", "Before a parcel exists, the tab shows whether the courier delivers to the address (serviceability, COD) and the promised dispatch time. Counter sales show the handover at the branch instead."],
    notes: ["Courier events are external evidence: the raw events are kept, and they never change the order or payment status.", "The courier is booked automatically when the parcel is packed; booking twice is prevented. Manual booking with the reference is the fallback.", "Delhivery is the sample courier in this prototype."],
    terms: ["awb", "manifest", "canonical-status", "serviceability", "rto", "otp"] },
  "d-timeline": { t: "Timeline", k: "Section",
    what: "Everything that happened to the order, in time order: created, priced, reserved, paid, invoiced, picked, dispatched — and any failures or requests along the way.",
    read: "Green = done · amber = something went wrong or needed attention · blue = where the order is now." },
  "d-audit": { t: "Audit trail", k: "Table",
    what: "Who changed what on this order: automatic rules (for example A09, which confirms an order when the payment is captured), the pricing engine writing the price snapshot, and staff actions. Even viewing the order is logged.",
    read: "Automatic changes show the rule and version and the duplicate-safe key they used, so a repeated message cannot apply twice.",
    terms: ["audit", "rule-codes", "idempotency"] },

  "x-late": { t: "Payment captured after reservation expiry", k: "Alert",
    what: "The customer paid after the stock reservation had expired, and the unit had meanwhile been reserved by another order. The system recorded the payment and put the order on hold automatically — it did not sell the same unit twice.",
    do: ["Finance (the named owner) decides by the due time.", "<b>Reserve alternate</b> holds a similar unit (here an open-box unit with the same configuration) and asks the customer to confirm — their agreement is needed because it is a different condition.", "<b>Refund</b> creates a refund request for finance if the customer does not want the alternative."],
    next: "If the customer accepts the alternative, the order is released to the warehouse with the new unit; otherwise the payment is refunded.",
    terms: ["reservation", "capture", "exception", "condition"] },
  "x-cancel-req": { t: "Cancellation request", k: "Alert",
    what: "The customer or dealer asked to cancel one line or the whole order. A line can be cancelled while it has not been dispatched — items already picked but not packed are still eligible and go back to their bin.",
    do: ["Click <b>Review</b> to open the cancellation form.", "Answer before the deadline shown."],
    rel: ["m-cancel", "sv-cancel"] },
  "x-gstin": { t: "On hold — GSTIN mismatch", k: "Alert",
    what: "The GST number (GSTIN) that would be printed on the business tax invoice does not match the dealer's approved profile — here the customer sent a new one by e-mail.",
    do: ["Finance verifies the new GSTIN before any business tax invoice is issued.", "When it is confirmed, click <b>Release hold</b>."],
    next: "The order goes back to the pick queue. The stock reservation is extended while the hold lasts.",
    terms: ["gstin", "kyc"] },
  "x-overdue": { t: "Overdue dispatch", k: "Alert",
    what: "The order missed its dispatch time because the picker found the bin empty although the system showed a unit allocated there. The mismatch automatically created a stock count task; a unit is free at another location.",
    do: ["Click <b>Request transfer</b> to move the unit from the other location to the warehouse.", "Keep the customer informed of the new date."],
    terms: ["bin", "cycle-count", "transfer"] },
  "x-failed": { t: "Delivery failed", k: "Alert",
    what: "The courier could not deliver — the receiver (consignee) could not be reached. The courier's raw message is shown. The order and payment statuses are unchanged.",
    do: ["Click <b>Ask customer</b> to send the address-check message, and confirm the address or phone before the next attempt."],
    next: "The courier tries again. After the last attempt (three in this sample) the parcel is returned to Tradex (RTO) and checked in quarantine.",
    terms: ["rto", "msg-template", "quarantine"] },
  "x-approval": { t: "Approval request", k: "Alert",
    what: "A staff member asked for a discount above their authority (here 14% against an 8% limit), which would also take the margin below the minimum (3.1% against a 6% floor). The request goes to the next approver with a deadline.",
    read: "The order stays a <b>Draft</b>: no stock is reserved and no payment link is sent until it is approved.",
    do: ["The approver clicks <b>Open approval</b> to see the request on the Automation page, then approves or rejects it with a reason."],
    notes: ["Authority limits and the margin floor are example values to be set by the client."],
    terms: ["approval", "margin", "override"] },
  "d-cancel": { t: "Cancel lines…", k: "Button",
    what: "Opens the cancellation form for this order. Only lines that have not been dispatched can be cancelled.",
    notes: ["It creates a refund request for finance — it does not pay money back by itself."], rel: ["m-cancel"] },
  "d-notify": { t: "Resend notification", k: "Button",
    what: "Sends an order message to the customer again: the confirmation by e-mail, the WhatsApp confirmation template, or an SMS with the tracking link.",
    read: "“Transactional · consent checked” means these are service messages about the purchase, not marketing. The line at the bottom shows the last delivery problem (for example a bounced e-mail) and when it is retried.",
    terms: ["consent", "msg-template", "service-window"] },

  /* ------------------------------------------------------------------ modals */
  "m-hold": { t: "Place order on hold", k: "Modal",
    what: "Stops an order from being released to the warehouse until an issue is resolved. The payment and the stock reservation are kept.",
    why: "Some problems — a tax number to verify, a payment to review, stock that is not where it should be — must be solved before anything ships. A hold makes the stop visible, owned and time-limited.",
    lists: [{ h: "Fields", items: [
      ["Reason", "Why the order is held (required) — see [[hold-reason]]."],
      ["Review by", "The time by which the owner should resolve it."],
      ["Owner", "Who is responsible for resolving the hold."],
      ["Note (internal)", "What must happen before release. Staff only."],
      ["Notify customer", "Optionally tells the customer the order is under review (message template order_review v1)."]] }],
    do: ["Choose the reason and the owner, set the review time and add a note.", "Click <b>Place on hold</b> (or <b>Cancel</b> to close without changes)."],
    next: "The order shows On hold and appears in the On hold and Needs action views. If the review time passes, it escalates once to the operations manager. The owner uses <b>Release hold</b> when resolved.",
    notes: ["The reservation is extended while on hold (up to 48 h in the prototype — a sample limit).", "The reason is recorded in the audit log."],
    terms: ["reservation", "audit", "msg-template"], rel: ["sv-hold"] },
  "hold-reason": { t: "Hold reason", k: "Field",
    what: "Why the order is being held. It is shown on the order and recorded in the audit log.",
    lists: [{ h: "Options", items: [
      ["Customer request — confirm details", "Waiting for the customer to confirm or change something."],
      ["Address / GSTIN verification", "The delivery address or the dealer's GST number must be checked."],
      ["Payment review (mismatch or risk)", "The payment does not match the order or looks risky."],
      ["Stock exception", "The stock is not where the system says it is."],
      ["Awaiting approval", "A decision from someone with authority is needed."]] }] },
  "m-cancel": { t: "Cancel line(s)", k: "Modal",
    what: "Cancels one or more lines of an order that have not been dispatched, and prepares the refund.",
    why: "Cancelling before dispatch is simpler for everyone than a return: the stock goes straight back to sale and the refund covers exactly what was paid for those lines.",
    read: ["Each line shows its value and whether it can be cancelled (not picked, or picked and to be returned to its bin). Greyed-out lines cannot be cancelled — shipped items come back through a return instead; a blue box explains when nothing on the order can be cancelled.", "The <b>Refund preview</b> shows what the customer gets back.", "The boxes on the right show the stock effect, any promotion effect and who pays the refund."],
    do: ["Tick the lines to cancel (lines the customer asked about are ticked for you).", "Choose the cancellation reason.", "Check the refund preview.", "Click <b>Cancel selected &amp; request refund</b>, or <b>Keep lines</b> to leave the order as it is."],
    next: "The lines are cancelled and their stock is released (a task is created to put picked items back in their bin). A refund request goes to finance, a credit note is issued, and the customer is notified. Finance approves and pays the refund.",
    notes: ["Support starts the refund; finance approves and executes it.", "Clicking twice returns the same refund request — the customer is never refunded twice."],
    terms: ["refund", "cn", "idempotency"], rel: ["cx-reason", "cx-refund", "cx-confirm"] },
  "cx-reason": { t: "Cancellation reason", k: "Field",
    what: "Why the lines are being cancelled. It is recorded with the cancellation.",
    lists: [{ h: "Options", items: [
      ["Customer request (before dispatch)", "The customer or dealer changed their mind."],
      ["Out of stock / cannot fulfil", "Tradex cannot supply the item."],
      ["Pricing error", "The item was sold at a wrong price."],
      ["Suspected fraud", "The order looks fraudulent."]] }] },
  "cx-refund": { t: "Refund preview", k: "Section",
    what: "How much the customer gets back for the selected lines.",
    read: ["<b>Line value</b> — before GST for dealers, including GST for consumers.", "<b>Allocated order discount</b> — the share of any order-level discount that belongs to these lines is taken off, so the refund matches what was actually paid.", "<b>GST</b> — added back for dealers, or the part included for consumers.", "<b>Refund to customer</b> — paid to the original payment method, with a credit note. If the payment was never captured, there is no refund — only the reservation is released."],
    notes: ["The refund uses the original prices and discount split stored on the order, not today's prices.", "If a cancellation takes an order below a promotion's minimum, the rule on whether the promotion is taken back is still a proposal for the client to confirm."],
    terms: ["refund", "cn", "snapshot", "promotion"] },
  "cx-confirm": { t: "Cancel selected & request refund", k: "Button",
    what: "Cancels the ticked lines now and sends one refund request to finance. The money is paid only after finance approves it.",
    notes: ["Clicking again returns the same refund request — no duplicate refund."], terms: ["idempotency", "refund"] },

  "m-assisted": { t: "New assisted order", k: "Modal",
    what: "Creates an order for a customer who is on the phone, on WhatsApp or at a branch counter. It uses the same pricing engine, stock reservation and payment rules as the website.",
    why: "Many customers — especially dealers — prefer to order by talking to someone. Assisted orders keep those sales on the same prices, stock and controls as online orders.",
    read: ["The coloured box at the top says where the order came from.", "On the left: customer, location, products, lines and the staff discount.", "On the right: the price summary, the estimated margin, the payment choice and the stock reservation note."],
    do: ["Check the order source and choose the customer.", "Choose the location that ships (the one that can supply every line is suggested first).", "Add products and quantities — prices come from the pricing engine.", "Add a discount only with a reason.", "Choose how the customer pays, then click <b>Send checkout link</b> (or <b>Submit for approval</b> if the discount is above your limit)."],
    next: "With a checkout link: stock is reserved and the order appears as Awaiting payment until the customer pays. With an approval request: the order waits as a Draft, with nothing reserved. <b>Save draft</b> keeps the work without reserving anything.",
    terms: ["assisted", "draft-basket", "checkout-link", "reservation", "approval"],
    rel: ["as-role", "as-source", "as-customer", "as-loc", "as-product", "as-rule", "as-discount", "as-approval", "as-summary", "as-payment", "as-submit"] },
  "as-role": { t: "Acting as (prototype)", k: "Setting",
    what: "A prototype-only switch to try this form as different staff roles and see how the discount limit changes: support executive up to 3%, branch manager up to 8%, owner without limit.",
    notes: ["In the real system your role comes from your sign-in. The limits are example thresholds to be set by the client."],
    terms: ["approval"] },
  "as-source": { t: "Order source", k: "Field",
    what: "How the customer reached you. Choose it with the buttons on the right of the box.",
    lists: [{ h: "Options", items: [
      ["WhatsApp basket", "Items and quantities come from the chat's draft basket. Prices mentioned in the chat are not trusted — every price is recalculated."],
      ["Phone", "Verify the caller first (a one-time code to the registered number) before showing account prices or order history."],
      ["Walk-in", "The customer is at the counter; they can pay at the till or through the link."]] }],
    terms: ["draft-basket", "otp"] },
  "as-customer": { t: "Customer", k: "Field",
    what: "The customer account the order is for. Its buyer type — consumer, or approved dealer and tier — comes from the approved account and cannot be changed on the order.",
    notes: ["Dealer prices are only used for verified members of an approved business account."],
    terms: ["b2c", "b2b", "price-list"] },
  "as-loc": { t: "Fulfil from", k: "Field",
    what: "The warehouse or branch that will supply the order, or customer pickup at a branch.",
    read: "A single location that can supply every line is suggested first. “1 line short” means that location cannot supply everything." },
  "as-product": { t: "Add product", k: "Field",
    what: "Search by name, model or SKU and click <b>Add</b>. Each result shows this customer's price (before GST for dealers, including GST for consumers) and the stock available.",
    read: "“Partner stock” is held by a supplier, not in a Tradex location — it ships in a few days.",
    terms: ["sku", "partner-stock", "atp"] },
  "as-rule": { t: "Unit price · rule", k: "Column",
    what: "The price per unit from the pricing engine, and the rule used (price list, version and quantity tier).",
    read: "A hint such as “+5 → tier 10+” means ordering 5 more units reaches the next quantity price. Changing the quantity recalculates the price.",
    terms: ["price-list"] },
  "as-discount": { t: "Staff discount", k: "Field",
    what: "An extra percentage discount given by staff, with a required reason.",
    read: "Within your authority it applies immediately and is recorded with your reason. Above your authority — or if it takes the margin below the floor — it becomes an approval request.",
    notes: ["Authority limits and the margin floor are example values to be set by the client."],
    terms: ["approval", "margin", "override"], rel: ["as-approval"] },
  "as-approval": { t: "Needs approval", k: "Alert",
    what: "The discount is above your authority, or takes the margin below the floor, so the order becomes an approval request. It goes to the branch manager — and on to the owner if above the manager's limit — with your reason, a deadline and an alternate approver.",
    read: "The order stays a <b>Draft</b>: no stock is reserved and no link is sent until it is approved.",
    notes: ["The routing, deadline and alternate approver shown are sample values."],
    terms: ["approval", "delegation"] },
  "as-summary": { t: "Price summary", k: "Section",
    what: "Subtotal, staff discount, GST, shipping and the amount payable, with the price list used.",
    read: "“Margin after discount (est.)” estimates the profit left after the discount, compared with the minimum margin (floor). Red means below the floor.",
    notes: ["The margin here is an estimate from illustrative cost figures in the prototype."],
    terms: ["margin", "landed", "gst"] },
  "as-payment": { t: "Payment", k: "Field",
    what: "How the customer will pay.",
    lists: [{ h: "Options", items: [
      ["Send secure checkout link", "By WhatsApp (while the service window is open), SMS or e-mail. The customer confirms the address and final price and pays through the payment provider."],
      ["Collect at branch counter (POS)", "UPI or card on the counter terminal; the invoice is printed at the counter."],
      ["Bank transfer (dealer prepaid)", "Released only after finance matches the money in the bank. Credit terms are not enabled."]] }],
    notes: ["Dealer orders are prepaid by default; buying on credit would need to be enabled separately."],
    terms: ["checkout-link", "service-window", "pos", "neft", "credit-limit"] },
  "as-submit": { t: "Send checkout link / Submit for approval", k: "Button",
    what: "The main button changes with the discount.",
    lists: [{ h: "Labels", items: [
      ["Send checkout link", "Sends the link to the customer and reserves the stock for a short time."],
      ["Submit for approval", "Sends the approval request; the order is saved as a Draft and nothing is reserved."]] }],
    rel: ["as-approval"], terms: ["checkout-link", "reservation"] },
});
